customAgentScenarioSteps.prompt:
# _{{remote-command}} _{{remote-content}} _{{remote-timeout-minutes}} _{{remote-out-subfolder}}
$ErrorActionPreference='Stop'
function Local-Path([string]$p){if(-not $IsWindows -and $p -match '^([A-Za-z]):[\\/](.*)$'){return '/mnt/'+$Matches[1].ToLowerInvariant()+'/'+$Matches[2].Replace('\','/')};return $p}
$source=Local-Path 'C:\Develop\BusinessEntityProduct\BusinessEntity\artifacts\botfactory-businessentity'
$payload=Join-Path '{TmpFolder}' 'businessentity-input'
New-Item -ItemType Directory -Force $payload|Out-Null
if((Get-FileHash (Join-Path $source 'manifest.json') -Algorithm SHA256).Hash -ne '1AB48678D05E7A805A13490CC18DC14A92DB4654967AF393BBE1BC1E09D83D71'){throw 'Pinned BusinessEntity payload changed; rebuild and republish scenario'}
$manifest=Get-Content (Join-Path $source 'manifest.json') -Raw|ConvertFrom-Json
Copy-Item (Join-Path $source 'manifest.json') $payload
foreach($entry in $manifest.files.PSObject.Properties){
 if($entry.Name -notin @('source.zip','host_install.py','request.json')){throw 'Unexpected payload'}
 if((Get-FileHash (Join-Path $source $entry.Name) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Payload hash mismatch'}
 Copy-Item (Join-Path $source $entry.Name) $payload
}
Write-Output '<<<BOTMGR_VARS_PACK_V1'
Write-Output (@{locals=@{vars=@(@{name='remote-command';value='BUSINESSENTITY-INSPECT;'},@{name='remote-content';value=$payload},@{name='remote-timeout-minutes';value='115'},@{name='remote-out-subfolder';value='businessentity-inspect'})}}|ConvertTo-Json -Depth 8 -Compress)
Write-Output 'BOTMGR_VARS_PACK_V1>>>'
